// Program.cs
// Convention-based registration
builder.Services.Scan(scan => scan
    .FromAssemblyOf<IProductService>()
    .AddClasses(classes => classes.AssignableTo<IProductService>())
    .AsImplementedInterfaces()
    .WithScopedLifetime());

// TryAdd pattern - only if not already registered
builder.Services.TryAddTransient<IEmailService, SmtpEmailService>();

// Factory registration
builder.Services.AddScoped<IProductService>(sp =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    var connectionString = config.GetConnectionString("Default");
    return new ProductService(connectionString);
});

// Keyed services (using factory)
builder.Services.AddSingleton<IEmailService>(sp =>
    sp.GetRequiredService<IEmailService>("Primary"));
